<template>
  <div class="register-container">
    <div class="register-wrapper">
      <div class="register-form-container">
        <div class="register-header">
          <img :src="logo" alt="团团赚拼购" class="logo" />
          <h2>用户注册</h2>
        </div>

        <El-form
          ref="registerFormRef"
          :model="registerForm"
          :rules="registerRules"
          class="register-form"
        >
          <El-form-item prop="username">
            <El-input
              v-model="registerForm.username"
              placeholder="用户名"
              clearable
            >
              <template #prefix>
                <El-icon><User /></El-icon>
              </template>
            </El-input>
          </El-form-item>

          <El-form-item prop="nickname">
            <!-- 新增昵称输入框 -->
            <El-input
              v-model="registerForm.nickname"
              placeholder="昵称"
              clearable
            >
              <template #prefix>
                <El-icon><User /></El-icon>
              </template>
            </El-input>
          </El-form-item>

          <El-form-item prop="phone">
            <El-input
              v-model="registerForm.phone"
              placeholder="手机号"
              clearable
            >
              <template #prefix>
                <El-icon><Phone /></El-icon>
              </template>
            </El-input>
          </El-form-item>

          <El-form-item prop="verifyCode" class="verify-code-item">
            <El-input
              v-model="registerForm.verifyCode"
              placeholder="验证码"
              class="verify-code-input"
            >
              <template #prefix>
                <El-icon><ChatDotRound /></El-icon>
              </template>
              <template #append>
                <El-button
                  :disabled="countDown > 0"
                  type="primary"
                  plain
                  @click="sendVerifyCode"
                >
                  {{ countDown > 0 ? `重发(${countDown}s)` : "获取验证码" }}
                </El-button>
              </template>
            </El-input>
          </El-form-item>

          <El-form-item prop="password">
            <El-input
              v-model="registerForm.password"
              type="password"
              placeholder="密码"
              show-password
            >
              <template #prefix>
                <El-icon><Lock /></El-icon>
              </template>
            </El-input>
          </El-form-item>

          <El-form-item prop="confirmPassword">
            <El-input
              v-model="registerForm.confirmPassword"
              type="password"
              placeholder="确认密码"
              show-password
            >
              <template #prefix>
                <El-icon><Lock /></El-icon>
              </template>
            </El-input>
          </El-form-item>

          <El-form-item>
            <El-button
              type="primary"
              class="register-btn"
              round
              block
              @click="handleRegister"
            >
              注 册
            </El-button>
          </El-form-item>

          <div class="register-footer">
            <El-link type="primary" @click="$router.push('/login')">
              已有账号？立即登录
            </El-link>
          </div>
        </El-form>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref } from "vue";
import { User, Lock, ChatDotRound, Phone } from "@element-plus/icons-vue"; // 也添加 Mobile 和 ChatDotRound 图标
const logo = "/assets/logo.png";

const registerFormRef = ref(null);
const registerForm = ref({
  username: "",
  nickname: "", // 添加昵称字段
  phone: "",
  verifyCode: "",
  password: "",
  confirmPassword: "",
});

// 倒计时和表单规则
const countDown = ref(0);

const registerRules = {
  username: [{ required: true, message: "请输入用户名", trigger: "blur" }],
  nickname: [
    { required: true, message: "请输入昵称", trigger: "blur" }, // 验证昵称
  ],
  phone: [
    { required: true, message: "请输入手机号", trigger: "blur" },
    {
      pattern: /^[1][3-9][0-9]{9}$/,
      message: "手机号格式不正确",
      trigger: "blur",
    },
  ],
  verifyCode: [{ required: true, message: "请输入验证码", trigger: "blur" }],
  password: [{ required: true, message: "请输入密码", trigger: "blur" }],
  confirmPassword: [
    { required: true, message: "请确认密码", trigger: "blur" },
    {
      validator: (rule, value, callback) => {
        if (value !== registerForm.value.password) {
          callback(new Error("两次密码输入不一致"));
        } else {
          callback();
        }
      },
      trigger: "blur",
    },
  ],
};

// 注册处理函数
const handleRegister = () => {
  registerFormRef.value.validate((valid) => {
    if (valid) {
      console.log("注册成功:", registerForm.value);

      // 发送注册请求的逻辑
      fetch("http://124.220.30.246/api/register", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          username: registerForm.value.username,
          nickname: registerForm.value.nickname, // 添加昵称字段
          phone: registerForm.value.phone,
          password: registerForm.value.password,
          verifyCode: registerForm.value.verifyCode, // 发送验证码
        }),
      })
        .then((response) => response.json())
        .then((data) => {
          if (data.id) {
            alert("注册成功！");
            // 可以选择重定向到登录页面
            // this.$router.push('/login');
          } else {
            alert(data.message || "注册失败，请重试。");
          }
        })
        .catch((error) => {
          console.error("请求错误:", error);
          alert("注册时发生错误，请稍后再试。");
        });
    } else {
      console.log("注册失败!");
      return false;
    }
  });
};

// 发送验证码
const sendVerifyCode = () => {
  if (registerForm.value.phone) {
    console.log("发送验证码到", registerForm.value.phone);

    // 发送验证码的 API 请求
    fetch("http://124.220.30.246/api/send-verification-code", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ phone: registerForm.value.phone }),
    })
      .then((response) => response.json())
      .then((data) => {
        if (data.success) {
          console.log("验证码发送成功");
          countDown.value = 60; // 60秒倒计时
          const timer = setInterval(() => {
            countDown.value--;
            if (countDown.value <= 0) {
              clearInterval(timer);
            }
          }, 1000);
        } else {
          console.error("验证码发送失败:", data.message);
          alert(data.message); // 显示错误信息
        }
      })
      .catch((error) => {
        console.error("请求错误:", error);
        alert("发送验证码时发生错误，请稍后再试。");
      });
  } else {
    alert("请输入手机号");
  }
};
</script>

